function GardenDibberDepthGaugeMaker.init() GardenDibberDepthGaugeMaker.ironStock=14; GardenDibberDepthGaugeMaker.bronzeStock=12; GardenDibberDepthGaugeMaker.woodStock=14; GardenDibberDepthGaugeMaker.leatherStock=8; GardenDibberDepthGaugeMaker.silverStock=8; GardenDibberDepthGaugeMaker.goldStock=6; GardenDibberDepthGaugeMaker.jewelStock=4; GardenDibberDepthGaugeMaker.pearlStock=4; GardenDibberDepthGaugeMaker.productStock={}; GardenDibberDepthGaugeMaker.buildings={}; GardenDibberDepthGaugeMaker.maker=nil; GardenDibberDepthGaugeMaker.activeMaking={}; GardenDibberDepthGaugeMaker.totalProducts=0; GardenDibberDepthGaugeMaker.dayTimer=0; print("[GardenDibberDepthGaugeMaker] Royal Garden Dibber Depth Gauge Maker System initialized (6 products, 4 buildings)") end
function GardenDibberDepthGaugeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GardenDibberDepthGaugeMaker.maker={name=n or ("Merilnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Merilnik najet: %s (spretnost: %d)",GardenDibberDepthGaugeMaker.maker.name,s),"success") end; return true end
function GardenDibberDepthGaugeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GardenDibberDepthGaugeMaker.build(id) local ok,e=GardenDibberDepthGaugeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GardenDibberDepthGaugeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
