function GardenDibberDepthGaugeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GardenDibberDepthGaugeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GardenDibberDepthGaugeMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GardenDibberDepthGaugeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GardenDibberDepthGaugeMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GardenDibberDepthGaugeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GardenDibberDepthGaugeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GardenDibberDepthGaugeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GardenDibberDepthGaugeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GardenDibberDepthGaugeMaker.buildings==0 then return false,"Potrebna merilna delavnica" end; if not GardenDibberDepthGaugeMaker.maker then return false,"Potreben merilnik" end; return true end
function GardenDibberDepthGaugeMaker.make(pt,qty) qty=qty or 1; local ok,e=GardenDibberDepthGaugeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GardenDibberDepthGaugeMaker.ironStock=GardenDibberDepthGaugeMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GardenDibberDepthGaugeMaker.bronzeStock=GardenDibberDepthGaugeMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GardenDibberDepthGaugeMaker.woodStock=GardenDibberDepthGaugeMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GardenDibberDepthGaugeMaker.leatherStock=GardenDibberDepthGaugeMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GardenDibberDepthGaugeMaker.silverStock=GardenDibberDepthGaugeMaker.silverStock-d.silverCost*qty end; if d.goldCost then GardenDibberDepthGaugeMaker.goldStock=GardenDibberDepthGaugeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GardenDibberDepthGaugeMaker.jewelStock=GardenDibberDepthGaugeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GardenDibberDepthGaugeMaker.pearlStock=GardenDibberDepthGaugeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GardenDibberDepthGaugeMaker.maker then t=math.max(1,t-math.floor(GardenDibberDepthGaugeMaker.maker.skill/13)) end; table.insert(GardenDibberDepthGaugeMaker.activeMaking,{id="gardendibberdepthgauge_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GardenDibberDepthGaugeMaker.completeMaking(m) local q=1.0+(GardenDibberDepthGaugeMaker.getQualityBonus()/100); if GardenDibberDepthGaugeMaker.maker then q=q+(GardenDibberDepthGaugeMaker.maker.skill/140) end; q=math.min(2.5,q); GardenDibberDepthGaugeMaker.productStock[m.productType]=(GardenDibberDepthGaugeMaker.productStock[m.productType] or 0)+m.quantity; GardenDibberDepthGaugeMaker.totalProducts=GardenDibberDepthGaugeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenDibberDepthGaugeMaker.maker then GardenDibberDepthGaugeMaker.maker.itemsMade=GardenDibberDepthGaugeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenDibberDepthGaugeMaker.maker.skill=math.min(100,GardenDibberDepthGaugeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Merilec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gardendibberdepthgauge.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GardenDibberDepthGaugeMaker.update(dt) if not _G.state then return end; GardenDibberDepthGaugeMaker.dayTimer=GardenDibberDepthGaugeMaker.dayTimer+dt; if GardenDibberDepthGaugeMaker.dayTimer>=30 then GardenDibberDepthGaugeMaker.dayTimer=0; for i=#GardenDibberDepthGaugeMaker.activeMaking,1,-1 do local m=GardenDibberDepthGaugeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GardenDibberDepthGaugeMaker.completeMaking(m); table.remove(GardenDibberDepthGaugeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GardenDibberDepthGaugeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GardenDibberDepthGaugeMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
